package com.bookstore.controller; import com.bookstore.repository.CustomerRepository; import com.bookstore.service.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; @Controller public class HomeController{private final BookService books;private final CustomerRepository customers;private final OrderService orders;public HomeController(BookService b,CustomerRepository c,OrderService o){books=b;customers=c;orders=o;}@GetMapping("/")String root(){return "redirect:/dashboard";}@GetMapping("/login")String login(){return "login";}@GetMapping("/dashboard")String dashboard(Model m){m.addAttribute("bookCount",books.count());m.addAttribute("customerCount",customers.count());m.addAttribute("orderCount",orders.count());m.addAttribute("sales",orders.totalSales());return "dashboard";}}